import json,hashlib,time,os,stat,pathlib
root=pathlib.Path(r"C:\dev\blog\death-of-software\projects\strehl")
base=root/"experiments/common-tiff-dimensions"
start=time.monotonic();cpu=time.process_time();read_count=0;refs={};values={};source={}
paths={
"result":base/"prepare-1/result.json","tail":base/"prepare-1/parent-tail.json","child":base/"prepare-1/child-00.json","log":base/"prepare-1/child-00.log",
"outer":base/"work/prepare-external-1-outer.json","stdout":base/"work/prepare-external-1-stdout.bin","stderr":base/"work/prepare-external-1-stderr.bin","exit":base/"work/prepare-external-1-exit.txt",
"release":base/"work/prepare-release-1.json","fixtures":base/"prepare-1/fixtures/index.json",
"runner":base/"run-stage.py","held":root/"experiments/m194h-pedestal-causality/build-and-run.py","checker":base/"independent-controls.py","preparer":base/"prepare-release.py",
"legacy_report":root/"experiments/common-tiff-stack/render-1/case-00/report.json"
}
def read(k,p):
 global read_count
 s=p.stat(follow_symlinks=False)
 if not stat.S_ISREG(s.st_mode) or s.st_size>1048576:raise ValueError("bounded regular file "+k)
 for parent in (p,*p.parents):
  q=parent.stat(follow_symlinks=False)
  if stat.S_ISLNK(q.st_mode) or getattr(q,"st_file_attributes",0)&0x400:raise ValueError("reparse "+k)
 if read_count+s.st_size>32*1048576:raise ValueError("read reservation")
 read_count+=s.st_size
 b=p.read_bytes();after=p.stat(follow_symlinks=False)
 if len(b)!=s.st_size or (s.st_size,s.st_mtime_ns,s.st_ino)!=(after.st_size,after.st_mtime_ns,after.st_ino):raise ValueError("unstable "+k)
 refs[k]={"path":str(p),"bytes":len(b),"sha256":hashlib.sha256(b).hexdigest()}
 if time.process_time()-cpu>9 or time.monotonic()-start>18:raise ValueError("read time")
 return b
for k,p in paths.items():
 b=read(k,p)
 if k in ("runner","held","checker","preparer"):source[k]=b.decode()
 elif k in ("log","stdout","stderr","exit"):values[k]=b.decode()
 else:values[k]=json.loads(b)
fi=values["fixtures"];values["fixture_index_summary"]={"schema":fi["schema"],"source":fi["source"],"spec":fi["spec"],"legacy":fi["legacy"],"generated_files_count":len(fi["generated_files"]),"cases":[{k:v for k,v in row.items() if k in ("id","ordinal","expected_exit_code","expected_folded_frames","version","manifest")} for row in fi["cases"]]}
del values["fixtures"]
rel=values["release"];values["release_summary"]={k:v for k,v in rel.items() if k!="source_bindings"};values["release_summary"]["source_bindings_count"]=len(rel["source_bindings"]);del values["release"]
files=[]
for e in os.scandir(base/"prepare-1/fixtures"):
 if len(files)>=64:raise ValueError("fixture metadata census cap")
 s=e.stat(follow_symlinks=False)
 if not stat.S_ISREG(s.st_mode) or getattr(s,"st_file_attributes",0)&0x400:raise ValueError("fixture ordinary file")
 files.append({"name":e.name,"bytes":s.st_size})
values["fixture_directory_metadata"]=sorted(files,key=lambda x:x["name"])
out={"refs":refs,"values":values,"source":source,"read_bytes":read_count,"cpu_sample":time.process_time()-cpu,"wall_sample":time.monotonic()-start}
print(json.dumps(out,sort_keys=True))
